-- Forecast the parts mix for problem P03, every region, next 12 weeks.
-- Target: rolling 4-week attach rate per candidate part (share of jobs using it).
-- Covariates known ahead: forecast temperature, install-base units at risk.
-- Generated by bigquery/make_sql.py.

WITH weekly AS (
  SELECT
    j.week, j.region, j.jobs,
    SUM(IF(u.part_id = 'BM-1/2HP', u.uses, 0)) AS bm_1_2hp,
    SUM(IF(u.part_id = 'CAP-10', u.uses, 0)) AS cap_10,
    SUM(IF(u.part_id = 'ECM-MOD', u.uses, 0)) AS ecm_mod,
    SUM(IF(u.part_id = 'CB-50A', u.uses, 0)) AS cb_50a,
    SUM(IF(u.part_id = 'BLR-RLY', u.uses, 0)) AS blr_rly
  FROM trunk.jobs_weekly AS j
  LEFT JOIN trunk.part_usage_weekly AS u
    USING (week, region, problem_code)
  WHERE j.problem_code = 'P03'
  GROUP BY j.week, j.region, j.jobs
),
rolling AS (
  SELECT
    week, region,
    SAFE_DIVIDE(SUM(bm_1_2hp) OVER w, SUM(jobs) OVER w) AS bm_1_2hp,
    SAFE_DIVIDE(SUM(cap_10) OVER w, SUM(jobs) OVER w) AS cap_10,
    SAFE_DIVIDE(SUM(ecm_mod) OVER w, SUM(jobs) OVER w) AS ecm_mod,
    SAFE_DIVIDE(SUM(cb_50a) OVER w, SUM(jobs) OVER w) AS cb_50a,
    SAFE_DIVIDE(SUM(blr_rly) OVER w, SUM(jobs) OVER w) AS blr_rly
  FROM weekly
  WINDOW w AS (PARTITION BY region ORDER BY week ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
),
-- History rows carry the targets; the 12 future rows carry NULL targets and
-- the covariates, which is how AI.FORECAST knows the horizon's conditions.
data AS (
  SELECT
    wx.week, wx.region,
    r.bm_1_2hp, r.cap_10, r.ecm_mod, r.cb_50a, r.blr_rly,
    wx.avg_temp_f,
    ib.units_at_risk
  FROM trunk.weather_weekly AS wx
  JOIN trunk.install_base_weekly AS ib
    ON ib.week = wx.week AND ib.region = wx.region AND ib.problem_code = 'P03'
  LEFT JOIN rolling AS r
    ON r.week = wx.week AND r.region = wx.region
)
SELECT *
FROM AI.FORECAST(
  TABLE data,
  model => 'TimesFM 3.0',
  timestamp_col => 'week',
  id_cols => ['region'],
  target_cols => ['bm_1_2hp', 'cap_10', 'ecm_mod', 'cb_50a', 'blr_rly'],
  future_covariate_cols => ['avg_temp_f', 'units_at_risk'],
  horizon => 12,
  confidence_level => 0.8       -- 80% interval: the 10th and 90th percentiles
);
